// findMax.js — locate the largest value in an array of numbers.

// Reject anything that is not a finite number so the scan cannot be
// poisoned by strings, null or NaN sneaking in from parsed input.
function assertNumericArray(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError('findMax expects an array');
  }
  // An empty array has no largest element, so there is nothing to return.
  if (arr.length === 0) {
    throw new RangeError('findMax expects a non-empty array');
  }
  arr.forEach((value, index) => {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`element at index ${index} is not a finite number: ${String(value)}`);
    }
  });
}

function findMax(arr) {
  assertNumericArray(arr);
  // Seed with the first element rather than -Infinity or 0, which keeps
  // all-negative inputs such as [-10, -2, -5] working correctly.
  let max = arr[0];
  for (let i = 1; i < arr.length; i += 1) {
    if (arr[i] > max) {
      max = arr[i];
    }
  }
  return max;
}

// Report the position of the maximum as well, useful for callers that need
// to know where the peak occurred and not just its value.
function findMaxIndex(arr) {
  const max = findMax(arr);
  return arr.indexOf(max);
}

// Turn a whitespace/comma separated line into numbers so the driver can
// accept data straight from the command line.
function parseNumberList(text) {
  return text
    .split(/[\s,]+/)
    .filter((token) => token.length > 0)
    .map((token) => {
      const value = Number(token);
      if (Number.isNaN(value)) {
        throw new TypeError(`cannot parse "${token}" as a number`);
      }
      return value;
    });
}

function describeMax(arr) {
  const max = findMax(arr);
  const index = findMaxIndex(arr);
  return `max([${arr.join(', ')}]) = ${max} at index ${index}`;
}

function main(argv) {
  // With arguments, treat them as one data set; otherwise use the task's samples.
  const datasets = argv.length > 0
    ? [parseNumberList(argv.join(' '))]
    : [[1, 5, 2, 8, 3], [-10, -2, -5]];

  for (const data of datasets) {
    try {
      console.log(describeMax(data));
    } catch (err) {
      // Bad input should not abort the remaining datasets.
      console.error(`skipping dataset: ${err.message}`);
    }
  }
}

module.exports = { findMax, findMaxIndex, parseNumberList, describeMax };

// Only run the driver when executed directly, not when required as a module.
if (require.main === module) {
  main(process.argv.slice(2));
}

