// Function to count vowels in a string
function countVowels(str) {
  // Initialize a counter for vowels
  let vowelCount = 0;

  // Define a string containing all vowels (lowercase)
  const vowels = "aeiou"; 

  // Convert the input string to lowercase to handle case-insensitivity
  const lowerStr = str.toLowerCase(); 

  // Iterate over each character in the lowercase string
  for (let i = 0; i < lowerStr.length; i++) {
    const char = lowerStr[i]; // Get the current character

    // Check if the current character is a vowel
    if (vowels.includes(char)) {
      // If it's a vowel, increment the counter
      vowelCount++; 
    }
  }

  // Return the total count of vowels
  return vowelCount; 
}

// Example usage 1: "Hello World" has 'e', 'o', 'o'
console.log(countVowels('Hello World')); // Expected output: 3

// Example usage 2: "JavaScript" has 'a', 'a', 'i'
console.log(countVowels('JavaScript')); // Expected output: 3

// Another example with all vowels
console.log(countVowels('AEIOU')); // Expected output: 5

// Example with no vowels
console.log(countVowels('Rhythm')); // Expected output: 0

// An empty string should return 0
console.log(countVowels('')); // Expected output: 0

// Test with mixed case and spaces
console.log(countVowels('aEiOu BcD')); // Expected output: 5
// This ensures handling of non-alphabetic characters as well.

