// Statistics helpers built around calculateAverage.

// Numeric guard: rejects NaN, Infinity and non-number types alike.
function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function calculateAverage(arr) {
  // Anything that is not a real array has no meaningful average.
  if (!Array.isArray(arr)) {
    throw new TypeError('calculateAverage expects an array');
  }

  // An empty array has no average; NaN signals that clearly.
  if (arr.length === 0) {
    return NaN;
  }

  let sum = 0;
  for (const value of arr) {
    // A single bad entry would poison the sum, so stop right away.
    if (!isFiniteNumber(value)) {
      throw new TypeError(`Not a finite number: ${String(value)}`);
    }
    sum += value;
  }

  return sum / arr.length;
}

// Sample standard deviation around the mean, needs at least two points.
function standardDeviation(arr) {
  const mean = calculateAverage(arr);
  if (arr.length < 2) {
    return 0;
  }
  const squaredDeviations = arr.map((value) => (value - mean) ** 2);
  // Bessel's correction: divide by n-1, so scale the mean of n terms back up.
  const variance = calculateAverage(squaredDeviations) * (arr.length / (arr.length - 1));
  return Math.sqrt(variance);
}

// Keeps only the values within `factor` standard deviations of the mean.
function withoutOutliers(arr, factor = 2) {
  const mean = calculateAverage(arr);
  const spread = standardDeviation(arr);
  if (spread === 0) {
    // All values identical (or a single value): nothing can be an outlier.
    return arr.slice();
  }
  return arr.filter((value) => Math.abs(value - mean) <= factor * spread);
}

function formatReport(label, arr) {
  const mean = calculateAverage(arr);
  // Number.isNaN distinguishes the empty-array case from a real mean of 0.
  const meanText = Number.isNaN(mean) ? 'n/a' : mean.toFixed(2);
  const trimmed = arr.length === 0 ? [] : withoutOutliers(arr);
  const trimmedMean = calculateAverage(trimmed);
  const trimmedText = Number.isNaN(trimmedMean) ? 'n/a' : trimmedMean.toFixed(2);
  return `${label}: n=${arr.length} mean=${meanText} sd=${standardDeviation(arr).toFixed(2)} trimmed=${trimmedText}`;
}

function main() {
  console.log(calculateAverage([10, 20, 30]));
  console.log(calculateAverage([5, 5, 5, 5]));

  const datasets = [
    ['temperatures', [18.5, 19.2, 20.1, 19.8, 34.0]],
    ['scores', [72, 88, 91, 64, 79, 85]],
    ['empty', []],
  ];

  for (const [label, values] of datasets) {
    console.log(formatReport(label, values));
  }

  try {
    calculateAverage([1, 2, 'three']);
  } catch (err) {
    // Surfacing the guard keeps bad input visible instead of silently skewing results.
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { calculateAverage, standardDeviation, withoutOutliers, formatReport };

