  const faces = [...counts.keys()].sort((a, b) => a - b);
  return faces
    .map((face) => {
      const n = counts.get(face);
      // Pad the face number so the bars line up for two-digit dice.
      const label = String(face).padStart(2, ' ');
      return `${label}: ${'#'.repeat(n)} (${n})`;
    })
    .join('\n');
}

