function addTask(schedule, taskName, startTime) {
  // Define the key for the current day's tasks
  const todayKey = 'today';

  // Check if 'today' already exists in the schedule object
  if (!schedule[todayKey]) {
    // If not, initialize it as an empty array
    schedule[todayKey] = [];
  }

  // Create a new task object with the given name and start time
  const newTask = {
    name: taskName,
    time: startTime
  };

  // Add the new task to the array for 'today'
  schedule[todayKey].push(newTask); // Push the task to the array

  // Return the modified schedule object
  return schedule; // The function returns the updated schedule
}

