// This function checks if a keyword is present in a given text.
// The search is performed in a case-insensitive manner.
const searchText = (text, keyword) => {
  // First, we need to handle edge cases for input.
  if (typeof text !== 'string' || typeof keyword !== 'string') {
    // Both inputs must be strings.
    throw new Error('Both text and keyword must be strings.');
  }

  // Convert both the text and the keyword to lowercase.
  // This ensures a case-insensitive comparison.
  const lowerText = text.toLowerCase(); // Convert text to lowercase.
  const lowerKeyword = keyword.toLowerCase(); // Convert keyword to lowercase.

  // Check if the lowercase keyword is an empty string.
  if (lowerKeyword === '') {
    // An empty keyword is considered to be found in any text.
    return true;
  }

  // Use the `includes` method to check for the keyword's presence.
  // The `includes()` method returns true if the string contains the specified value.
  return lowerText.includes(lowerKeyword); // Perform the actual search.
};

