const isValidEmail = (email) => { // Defines a function named isValidEmail that takes an email string as input.
  if (typeof email !== 'string') { // Checks if the input is actually a string.
    return false; // Returns false if the input is not a string.
  }

  // A simple regex for basic email validation.
  // It checks for:
  // - one or more characters before '@'
  // - an '@' symbol
  // - one or more characters after '@'
  // - a dot '.'
  // - two or more characters after the dot (for the top-level domain)
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/; // This is the regular expression pattern.

  return emailRegex.test(email); // Tests the email string against the regex pattern.
};

