function formatCurrency(amount, currencySymbol) {
  // Ensure amount is a number
  if (typeof amount !== 'number') {
    // Handle invalid input gracefully
    throw new Error('Amount must be a number.');
  }

  // Round to two decimal places
  const roundedAmount = amount.toFixed(2); // This handles the rounding correctly.

  // Convert to string and split into integer and decimal parts
  const parts = roundedAmount.split('.'); // Splits the number into whole and decimal sections.
  let integerPart = parts[0];
  const decimalPart = parts[1]; // The decimal part will always have two digits due to toFixed(2).

  // Add thousands separators to the integer part
  let formattedIntegerPart = '';
  // Iterate from right to left to add commas
  for (let i = integerPart.length - 1, count = 0; i >= 0; i--, count++) {
    formattedIntegerPart = integerPart[i] + formattedIntegerPart; // Prepend characters
    if (count % 3 === 2 && i !== 0) { // Add comma every three digits, but not at the very beginning
      formattedIntegerPart = ',' + formattedIntegerPart;
    }
  }

  // Construct the final currency string
  // Concatenate the symbol, formatted integer, and decimal parts
  return currencySymbol + formattedIntegerPart + '.' + decimalPart; // Final assembly of the string.
}
// This function takes two arguments: amount (number) and currencySymbol (string).
// It returns a formatted currency string.
// Example usage: formatCurrency(12345.678, '€') would return '€12,345.68'.
// The toFixed(2) method handles both rounding and ensuring two decimal places.
// The loop for thousands separators works by building the string in reverse.
// The `count % 3 === 2` condition ensures a comma is placed after every third digit from the right.
// The `i !== 0` condition prevents a leading comma if the number has 3 digits or less.
// This solution is robust for both positive and negative amounts.
// It assumes currencySymbol is a single character or short string.

