const formatCountdown = (seconds) => {
  // Calculate minutes from total seconds
  const minutes = Math.floor(seconds / 60);

  // Calculate remaining seconds after extracting minutes
  const remainingSeconds = seconds % 60;

  // Format minutes to always be two digits
  const formattedMinutes = String(minutes).padStart(2, '0');

  // Format seconds to always be two digits
  const formattedSeconds = String(remainingSeconds).padStart(2, '0');

  // Concatenate minutes and seconds with a colon
  return `${formattedMinutes}:${formattedSeconds}`; // Return the formatted string
};
