  // Initialize an empty object to store the grouped results.
  const result = {};

  // Iterate over each object in the input array.
  for (const obj of arr) {
    // Get the value of the specified property for the current object.
    const propertyValue = obj[prop];

    // Check if a key for this property value already exists in the result object.
    if (!result[propertyValue]) {
