const doRectanglesOverlap = (rect1, rect2) => {
  // Extract coordinates for the first rectangle
  const [r1x1, r1y1, r1x2, r1y2] = rect1;

  // Extract coordinates for the second rectangle
  const [r2x1, r2y1, r2x2, r2y2] = rect2;

  // Check if one rectangle is to the left of the other
  if (r1x1 >= r2x2 || r2x1 >= r1x2) {
    return false; // No horizontal overlap
