const getNestedProperty = (obj, path) => {
  // Check if the object is null or undefined early.
  if (obj === null || typeof obj === 'undefined') {
    return undefined;
  }

  // Split the path string into an array of keys.
  const keys = path.split('.');
  let current = obj; // Initialize current with the given object.

  // Iterate over each key in the path.
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i]; // Get the current key.

    // If current is not an object or the key doesn't exist, return undefined.
    if (typeof current !== 'object' || current === null || !current.hasOwnProperty(key)) {
      // This handles cases where a property in the path is missing or not an object.
      return undefined;
    }
    // Move to the next nested level.
    current = current[key];
  }

  // After iterating through all keys, current holds the final value.
  return current;
};

