// invertObject plus a small checker and reporting driver around it.

// Values become keys, so they must be usable as property names.
function stringifyValue(value) {
    // Symbols throw when coerced implicitly, so convert them explicitly.
    if (typeof value === 'symbol') {
        return value.toString();
    }
    return String(value);
}

function invertObject(obj) {
    // Only objects carry own enumerable keys to swap.
    if (obj === null || typeof obj !== 'object') {
        throw new TypeError('invertObject expects an object');
    }
    const inverted = {};
    for (const key of Object.keys(obj)) {
        // The stringified value becomes the new key, the old key the new value.
        inverted[stringifyValue(obj[key])] = key;
    }
    return inverted;
}

// Verifies the "all values are unique" assumption before inverting.
function findCollisions(obj) {
    const seen = new Map();
    const collisions = [];
    for (const key of Object.keys(obj)) {
        const stringified = stringifyValue(obj[key]);
        if (seen.has(stringified)) {
            // Two distinct keys would collapse onto one inverted key.
            collisions.push(stringified + ' <- ' + seen.get(stringified) + ', ' + key);
        } else {
            seen.set(stringified, key);
        }
    }
    return collisions;
}

// Inverts only when the assumption holds, otherwise explains the problem.
function safeInvert(obj) {
    const collisions = findCollisions(obj);
    if (collisions.length > 0) {
        throw new Error('duplicate values prevent inversion: ' + collisions.join('; '));
    }
    return invertObject(obj);
}

function formatObject(obj) {
    const pairs = Object.keys(obj).map(function (k) {
        return "'" + k + "': '" + obj[k] + "'";
    });
    return '{ ' + pairs.join(', ') + ' }';
}

function report(obj) {
    try {
        // Successful inversions are printed as a readable mapping.
        console.log(formatObject(obj) + ' -> ' + formatObject(safeInvert(obj)));
    } catch (err) {
        // Uniqueness failures are reported instead of crashing the run.
        console.log(formatObject(obj) + ' -> ' + err.message);
    }
}

report({ a: 1, b: 2 });
report({ name: 'Alice', age: 30 });
report({ x: true, y: null, z: undefined });
report({ first: 'dup', second: 'dup' });

module.exports = { invertObject, safeInvert, findCollisions };

