const getInitials = (fullName) => {
  // Trim any leading or trailing whitespace from the full name
  const trimmedName = fullName.trim(); 

  // Split the full name into an array of individual names
  // This handles multiple spaces between names gracefully, producing empty strings that will be filtered out.
  const nameParts = trimmedName.split(' '); 

  // Filter out any empty strings that might result from multiple spaces
  // This ensures that only actual name components are processed.
  const filteredParts = nameParts.filter(part => part !== ''); 

  // Map each name part to its first character (initial)
  const initialsArray = filteredParts.map(part => {
    // Get the first character of each non-empty name part
    return part[0]; 
  });

  // Convert the array of initials to uppercase
  const upperCaseInitials = initialsArray.map(initial => initial.toUpperCase());

  // Join the uppercase initials into a single string
  const initials = upperCaseInitials.join(''); 

  // Return the final string of initials
  return initials; // The final result is returned here.
};

