const calculateInventoryValue = (items) => { // Defines the function to calculate inventory value.
  let totalValue = 0; // Initializes a variable to store the cumulative total value.

  // Check if the input is an array and not null.
  if (!Array.isArray(items) || items === null) {
    return 0; // Returns 0 if the input is invalid.
  }

  // Iterate over each item in the provided array.
  for (let i = 0; i < items.length; i++) {
    const item = items[i]; // Get the current item object.

    // Ensure item is an object and has required properties.
    if (typeof item !== 'object' || item === null || !('price' in item) || !('quantity' in item)) {
      continue; // Skip this item if it's malformed.
    }

    // Extract price and quantity, defaulting to 0 if not a valid number.
    const price = typeof item.price === 'number' && !isNaN(item.price) ? item.price : 0;
    const quantity = typeof item.quantity === 'number' && !isNaN(item.quantity) ? item.quantity : 0;

    // Prices and quantities should be non-negative.
    if (price < 0 || quantity < 0) {
      continue; // Skip items with negative values.
    }

    // Calculate the value for the current item.
    const itemValue = price * quantity; // Calculates the value for the current item.
    totalValue += itemValue; // Adds the item's value to the running total.
  }

  return totalValue; // Returns the final calculated total inventory value.
};
// This function handles various edge cases for robustness.

