function isValidHexColor(hex) {
  // Check if the input is a string
  if (typeof hex !== 'string') {
    return false;
  }

  // A valid hex color must start with '#'
  if (hex[0] !== '#') {
    return false;
  }

  // Remove the '#' character
  const hexValue = hex.substring(1);

  // Get the length of the hex value
