const filterByProps = (data, filter) => {
  // Get all keys from the filter object
  const filterKeys = Object.keys(filter);

  // Return the filtered array
  return data.filter(item => {
    // Check if every key-value pair in the filter matches the current item
    return filterKeys.every(key => {
      // Ensure the item has the key and its value matches the filter's value
      return item.hasOwnProperty(key) && item[key] === filter[key];
    });
  });
};

