const isWeekend = (date) => {
  // Get the day of the week, where 0 is Sunday and 6 is Saturday.
  const dayOfWeek = date.getDay(); 

  // Check if the day is a Saturday (6) or a Sunday (0).
  if (dayOfWeek === 0 || dayOfWeek === 6) {
    return true; // It's a weekend.
  } else {
    // It's a weekday.
    return false; 
  }
};

// Example usage:
// This date is a Saturday.
const saturday = new Date('2023-10-28'); 
console.log(isWeekend(saturday)); // Expected: true

// This date is a Friday.
const friday = new Date('2023-10-27'); 
console.log(isWeekend(friday)); // Expected: false

// This date is a Sunday.
const sunday = new Date('2023-10-29');
console.log(isWeekend(sunday)); // Expected: true

