// Helpers for a single CSV record: split it into fields, then classify and report on them.

function parseCsvLine(csvLine) {
  if (typeof csvLine !== 'string') {
    // Fail loudly here instead of letting a missing split method confuse the caller
    throw new TypeError('parseCsvLine expects a string');
  }

  let line = csvLine;

  if (line.endsWith('\r\n')) {
    // Drop the Windows terminator so lines read from a file match lines built in code
    line = line.slice(0, -2);
  } else if (line.endsWith('\n')) {
    // Same for a plain Unix terminator
    line = line.slice(0, -1);
  }

  if (line === '') {
    // An empty record holds no fields, whereas split would report one empty field
    return [];
  }

  return line.split(',');
}

function classifyField(field) {
  const trimmed = field.trim();

  if (trimmed === '') {
    // A field of only whitespace carries no value at all
    return 'empty';
  }

  const asNumber = Number(trimmed);

  if (Number.isNaN(asNumber)) {
    // Anything that does not convert cleanly is treated as free text
    return 'text';
  }

  // Blank input would have converted to zero, which is why it was settled above
  return Number.isInteger(asNumber) ? 'integer' : 'decimal';
}

function describeLine(csvLine) {
  return parseCsvLine(csvLine).map(function (field, index) {
    return { index: index, value: field, kind: classifyField(field) };
  });
}

function formatReport(csvLine) {
  const described = describeLine(csvLine);

  if (described.length === 0) {
    // Say so explicitly rather than printing an empty listing
    return 'no fields';
  }

  const rows = described.map(function (entry) {
    // Quoting keeps padded and empty fields visible in the output
    const shown = JSON.stringify(entry.value);
    return '  [' + entry.index + '] ' + shown + ' -> ' + entry.kind;
  });

  return described.length + ' field(s):\n' + rows.join('\n');
}

function main() {
  const lines = process.argv.slice(2);

  if (lines.length === 0) {
    // Nothing to parse, so explain the expected invocation
    console.error('usage: node csvline.js <csv-line> [...]');
    return;
  }

  for (const line of lines) {
    console.log(formatReport(line));
  }
}

if (require.main === module) {
  main();
}

module.exports = { parseCsvLine, classifyField, describeLine, formatReport };

