function calculateBMI(weightKg, heightM) {
  // Ensure height is not zero to prevent division by zero
  if (heightM === 0) {
    throw new Error("Height cannot be zero.");
  }

  // Calculate the square of the height
  const heightSquared = heightM * heightM;

  // Calculate BMI using the formula: weight / (height * height)
  const bmi = weightKg / heightSquared;

  // Return the calculated BMI
  return bmi;
}

// Example usage 1:
const bmi1 = calculateBMI(70, 1.75); // Weight 70kg, Height 1.75m
// Log the first BMI result
console.log(bmi1);

// Example usage 2:
const bmi2 = calculateBMI(90, 1.80); // Weight 90kg, Height 1.80m
// Log the second BMI result
console.log(bmi2);

// Another example with different values
const bmi3 = calculateBMI(65, 1.60);
// This will calculate BMI for 65kg and 1.6m
console.log(bmi3);

