// hasProperty reports whether propName is an own, non-inherited property of obj
function hasProperty(obj, propName) {
  // primitives and null carry no own properties we can inspect
  if (obj === null || (typeof obj !== 'object' && typeof obj !== 'function')) {
    return false;
  }
  // symbols are valid keys, so only non-symbol names get coerced to strings
  const key = typeof propName === 'symbol' ? propName : String(propName);
  return Object.prototype.hasOwnProperty.call(obj, key);
}

// ownKeys lists every own key, including symbols and non-enumerable ones
function ownKeys(obj) {
  if (obj === null || (typeof obj !== 'object' && typeof obj !== 'function')) {
    return [];
  }
  return Reflect.ownKeys(obj);
}

// missingProperties returns the required names the object does not define itself
function missingProperties(obj, required) {
  return required.filter(function (name) {
    return !hasProperty(obj, name);
  });
}

// describeProperty separates own keys from inherited ones by walking the chain
function describeProperty(obj, propName) {
  if (hasProperty(obj, propName)) {
    return 'own';
  }
  let proto = obj === null || obj === undefined ? null : Object.getPrototypeOf(obj);
  while (proto !== null) {
    if (hasProperty(proto, propName)) {
      return 'inherited';
    }
    proto = Object.getPrototypeOf(proto);
  }
  return 'absent';
}

// report renders one readable line per requested property
function report(label, obj, names) {
  const keys = ownKeys(obj).map(String).join(', ') || 'none';
  const lines = names.map(function (name) {
    return '  ' + String(name) + ': ' + describeProperty(obj, name);
  });
  return [label + ' (own keys: ' + keys + ')'].concat(lines).join('\n');
}

class Point {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }
  norm() {
    return Math.hypot(this.x, this.y);
  }
}

console.log(hasProperty({ a: 1, b: 2 }, 'a'));
console.log(hasProperty({ x: 10 }, 'y'));

// toString comes from Object.prototype, so it is never an own property
console.log(hasProperty({}, 'toString'));

const tag = Symbol('tag');
const config = { host: 'localhost', port: 8080, [tag]: 'dev' };
// an own property set to undefined still counts as present
config.timeout = undefined;
console.log(report('config', config, ['host', 'port', 'timeout', 'retries', tag, 'toString']));

const missing = missingProperties(config, ['host', 'port', 'retries']);
if (missing.length > 0) {
  console.log('config is missing: ' + missing.join(', '));
}

// arrays own their indices and length, but their methods live on the prototype
console.log(report('list', ['a', 'b'], ['0', 1, 'length', 'push']));

// instance fields are own properties while class methods are inherited
console.log(report('point', new Point(3, 4), ['x', 'y', 'norm', 'z']));

// a null-prototype bag inherits nothing at all
const bag = Object.create(null);
bag.only = true;
console.log(report('bag', bag, ['only', 'toString']));

